PATHS = {k: v["path"] for k, v in ENDPOINTS.items()}

_ENCODED_PATHS = sorted(
    ((v["path"], v["encoding"]) for v in ENDPOINTS.values() if "encoding" in v),
    key=lambda p: -len(p[0]),
)


def seg(value) -> str:
    return quote(str(value), safe="")


def url(key: str, **params) -> str:
    endpoint = ENDPOINTS[key]
    path = endpoint["path"]
    for name in endpoint.get("params", ()):
        if name not in params:
            raise KeyError(f"missing path param {name!r} for endpoint {key!r}")
        path = path.replace("{" + name + "}", seg(params[name]))
    return path


def query_string(params: dict | None) -> str:
    pairs = [(k, v) for k, v in (params or {}).items() if v is not None]
    if not pairs:
        return ""
    return "?" + "&".join(f"{seg(k)}={seg(v)}" for k, v in pairs)


def encoding_for(key: str) -> str:
    return ENDPOINTS[key].get("encoding", "generic")


def encoding_for_path(path: str) -> str:
    for prefix, enc in _ENCODED_PATHS:
        if path.startswith(prefix):
            return enc
    return "generic"
